window.addEventListener('load',()=>{
const PLANETS={"venus": "data:image/jpeg;base64,", "uranus": "data:image/jpeg;base64,", "earth": "data:image/jpeg;base64,", "saturn": "data:image/jpeg;base64,", "jupiter": "data:image/jpeg;base64,", "mars": "data:image/jpeg;base64,", "mercury": "data:image/jpeg;base64,", "neptune": "data:image/jpeg;base64,", "pluto": "data:image/jpeg;base64,"};
const CORE="data:image/png;base64,";
const LABELS=['PEOPLE','TECHNOLOGY','BUSINESS','POSSIBILITY','INNOVATION','CONNECTION','GROWTH','IMPACT','VISION'];
const ORDER=['earth','jupiter','mars','mercury','neptune','pluto','saturn','uranus','venus'];
const visionCanvas=document.getElementById('visionPlanetCanvas'),ctx=visionCanvas.getContext('2d');
const stage=document.getElementById('visionOrbitalStage'), visionCore=document.getElementById('visionCore'), visionCoreImg=document.getElementById('visionCoreImg');visionCoreImg.src='assets/core-reference-cosmic-blue.png';
const images={}; ORDER.forEach(n=>{const im=new Image();im.src=PLANETS[n];images[n]=im;});
const state={w:0,h:0,cx:0,cy:0,r:285,planetR:58,angle:0,last:performance.now()};
function fit(){const r=stage.getBoundingClientRect();state.w=Math.max(1,r.width);state.h=Math.max(1,r.height);visionCanvas.width=Math.floor(state.w*devicePixelRatio);visionCanvas.height=Math.floor(state.h*devicePixelRatio);visionCanvas.style.width=state.w+'px';visionCanvas.style.height=state.h+'px';ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);
const vw=window.innerWidth; const mobile=vw<=900; const tablet=vw<=1500 && !mobile; const tabletWide=vw>1100; const safe=Math.min(state.h*(mobile?0.42:tablet?0.39:0.39),state.w*(mobile?0.46:tablet?0.50:0.40)); state.planetR=mobile?Math.max(31,Math.min(48,state.h*0.072)):tablet?Math.max(44,Math.min(tabletWide?56:50,state.h*0.068)):Math.max(48,Math.min(72,state.h*0.082)); state.cx=mobile?state.w*0.50:tablet?state.w*0.50:state.w*0.56; state.cy=state.h*0.50; state.r=mobile?Math.max(90,Math.min(215,safe,state.w*0.50-state.planetR-8)):tablet?Math.max(125,Math.min(tabletWide?285:175,safe,state.w*0.50-state.planetR-12)):Math.max(190,Math.min(335,safe));visionCore.style.left=state.cx+'px';visionCore.style.top=state.cy+'px';}
window.addEventListener('resize',fit);fit();
function wrapShift(im, sx, sy, sw, sh, dx,dy,dw,dh){const W=im.naturalWidth,H=im.naturalHeight; if(!W||!H)return; if(sx+sw<=W){ctx.drawImage(im,sx,sy,sw,sh,dx,dy,dw,dh);} else {const a=W-sx;const aw=dw*a/sw;ctx.drawImage(im,sx,sy,a,sh,dx,dy,aw,dh);ctx.drawImage(im,0,sy,sw-a,sh,dx+aw,dy,dw-aw,dh);}}
function drawPlanet(im,x,y,r,rot,label,name){ctx.save();const glow=ctx.createRadialGradient(x,y,r*.35,x,y,r*1.55);glow.addColorStop(0,'rgba(246,213,139,.20)');glow.addColorStop(.62,'rgba(246,213,139,.07)');glow.addColorStop(1,'rgba(246,213,139,0)');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(x,y,r*1.55,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.clip();const sw=im.naturalWidth/2;const sx=((rot%(im.naturalWidth))+im.naturalWidth)%im.naturalWidth;wrapShift(im,sx,0,sw,im.naturalHeight,x-r,y-r,r*2,r*2);const shade=ctx.createRadialGradient(x-r*.25,y-r*.35,r*.08,x,y,r*1.25);shade.addColorStop(0,'rgba(255,255,255,.12)');shade.addColorStop(.45,'rgba(0,0,0,0)');shade.addColorStop(.82,'rgba(0,0,0,.23)');shade.addColorStop(1,'rgba(0,0,0,.62)');ctx.fillStyle=shade;ctx.fillRect(x-r,y-r,2*r,2*r);ctx.restore();
ctx.save();ctx.strokeStyle='rgba(255,255,255,.18)';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,r+.5,0,Math.PI*2);ctx.stroke();const maxW=r*1.70;let fs=Math.max(10,r*.36);ctx.font='700 '+fs+'px Inter,Arial,sans-serif';while(ctx.measureText(label).width>maxW && fs>9.5){fs-=.35;ctx.font='700 '+fs+'px Inter,Arial,sans-serif';}const tw=ctx.measureText(label).width;const ph=Math.max(22,fs*1.70),pw=Math.min(tw+20,r*1.78);ctx.fillStyle='rgba(0,0,0,.46)';ctx.beginPath();const rr=ph/2;ctx.roundRect(x-pw/2,y-ph/2,pw,ph,rr);ctx.fill();ctx.strokeStyle='rgba(242,194,95,.58)';ctx.lineWidth=.8;ctx.stroke();ctx.fillStyle='#F6D58B';ctx.font='700 '+fs+'px Inter,Arial,sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.shadowColor='rgba(0,0,0,.98)';ctx.shadowBlur=8;ctx.fillText(label,x,y+.5);ctx.restore();}
function drawOrbit(){ctx.save();ctx.strokeStyle='rgba(242,194,95,.20)';ctx.lineWidth=1;ctx.beginPath();ctx.arc(state.cx,state.cy,state.r,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='rgba(242,194,95,.06)';ctx.beginPath();ctx.arc(state.cx,state.cy,state.r+9,0,Math.PI*2);ctx.stroke();ctx.restore();}
function frame(now){const dt=Math.min(.033,(now-state.last)/1000);state.last=now;state.angle+=dt*.18;ctx.clearRect(0,0,state.w,state.h);drawOrbit();for(let i=0;i<9;i++){const a=state.angle-0.43+i*Math.PI*2/9;const x=state.cx+state.r*Math.cos(a);const y=state.cy+state.r*Math.sin(a);const n=ORDER[i];const im=images[n];if(im.complete) drawPlanet(im,x,y,state.planetR,(now*.02*(i%2?1:-1)*0.75)%im.naturalWidth,LABELS[i],n);}requestAnimationFrame(frame)}requestAnimationFrame(frame);
});